        return 0;
    }

    static TreeNode buildTree(List<String> tokens, int count) {
        if (count == 0 || tokens.get(0).equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(tokens.get(0)));
        ArrayList<TreeNode> queue = new ArrayList<>();
        queue.add(root);
        int head = 0, i = 1;
        while (head < queue.size() && i < count) {
            TreeNode node = queue.get(head++);
            if (i < count && !tokens.get(i).equals("null")) {
                node.left = new TreeNode(Integer.parseInt(tokens.get(i)));
                queue.add(node.left);
            }
            i++;
            if (i < count && !tokens.get(i).equals("null")) {
                node.right = new TreeNode(Integer.parseInt(tokens.get(i)));
                queue.add(node.right);
            }
            i++;
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tokens.add(st.nextToken());
        }
        int k = Integer.parseInt(tokens.get(tokens.size() - 1));
        TreeNode root = buildTree(tokens, tokens.size() - 1);
        System.out.println(kthSmallest(root, k));
    }
}
